test('exit and re-entry during each real phase never cancel, reset, replay, or change a pending transaction',()=>{
 const stages=['idle','coin','funded','drop','deliver','ready','taking','jammed','recovering','recovered','returning','restocking'];
 for(const at of stages){
  const f=fixture();enter(f);if(at==='coin'){f.action('lessonNext');f.tick(.2);}else if(at==='funded'){f.action('lessonNext');f.finish();}else if(at==='restocking'){f.s.stock[0]=2;f.action('refill');f.tick(.2);}else if(at!=='idle'){insert(f,2);if(['jammed','recovering','recovered','returning'].includes(at))f.action('faultNext');choice(f,'flavor-1');if(at==='drop')f.tick(.2);else if(at==='deliver')f.tick(1.96);else{f.finish();if(at==='taking'){f.action('lessonNext');f.tick(.2);}if(at==='recovering'||at==='recovered'){f.action('lessonNext');if(at==='recovering')f.tick(.2);else f.finish();}if(at==='returning'){choice(f,'cancel');f.tick(.8);}}}
  assert.equal(f.s.phase,at==='funded'?'idle':at);const before=state(f),pose=f.s.delivered===null?null:f.pose();f.action('lessonExit');assert.equal(state(f),before);assert.deepEqual(f.s.delivered===null?null:f.pose(),pose);for(let n=0;n<20;n++){f.action('lessonNext');choice(f,'continue');choice(f,'cancel');choice(f,'flavor-2');}assert.equal(state(f),before,'closed controls inert at '+at);enter(f);assert.equal(state(f),before);f.action('lessonExit');f.finish();if(f.s.phase==='jammed'){f.action('recover');f.finish();}if(f.s.phase==='recovered'){f.action('continue');f.finish();}if(f.s.phase==='ready'){f.action('collect');f.finish();}if(f.s.tokens){f.action('refund');f.finish();}assert.equal(f.s.phase,'idle');assert.equal(f.s.delivered,null);assert.equal(f.s.reservedCoin,0);
 }
});
