  const f=fixture();enter(f);if(at==='coin'){f.action('lessonNext');f.tick(.2);}else if(at!=='idle'){insert(f,2);if(['drop','jammed','recovering','recovered','returning'].includes(at))f.action('faultNext');choice(f,'flavor-0');if(at==='drop')f.tick(.2);else{f.finish();if(['recovering','recovered'].includes(at)){f.action('lessonNext');if(at==='recovering')f.tick(.2);else f.finish();}if(at==='returning'){choice(f,'cancel');f.tick(.8);}if(at==='taking'||at==='completed'){f.action('lessonNext');if(at==='taking')f.tick(.2);else f.finish();}}}
