test('real shared guide starts collapsed, promotes one original control group, and returns it intact on exit or parent fold',()=>{
 const f=fixture(),o=f.mount(),go=o.guide.querySelector('.mechanism-lesson-go'),exit=o.guide.querySelector('.mechanism-lesson-exit'),originalButtons=[...o.primary.children];assert.equal(o.guide.open,false);assert.equal(o.primary.parentElement,o.dock);assert.equal(o.dock.classList.contains('lesson-guiding'),false);assert.equal(o.guide.querySelector('.mechanism-lesson-hold').hidden,false,'unopened body need not be populated');
 o.openGuide();assert.equal(o.guide.parentElement,o.dock);assert.equal(o.dock.classList.contains('lesson-guiding'),true);assert.equal(o.primary.parentElement.className,'lesson-free-controls vending-free-controls');assert.equal(o.primary.parentElement.open,false);assert.equal(o.guide.querySelector('.mechanism-lesson-hold').hidden,true,'no unsupported pause button');assert.equal(o.guide.querySelector('.mechanism-lesson-choices').hidden,true);assert.equal(go.hidden,false);go.onclick();assert.equal(f.s.phase,'coin');assert.equal(go.getAttribute('aria-disabled'),'true');const during=state(f);go.onclick();assert.equal(state(f),during);f.finish();assert.equal(go.hidden,true);const choices=o.guide.querySelector('.mechanism-lesson-choices'),flavor=choices.children.find(button=>button.dataset.choice==='flavor-1');assert(flavor);flavor.onclick();assert.equal(f.s.delivered,1);assert.equal(go.hidden,false);const releasing=state(f);flavor.onclick();assert.equal(state(f),releasing,'stale DOM choice cannot buy twice');exit.onclick();assert.equal(state(f),releasing);assert.equal(o.guide.open,false);assert.equal(o.primary.parentElement,o.dock);assert.deepEqual(o.primary.children,originalButtons);assert.equal(o.guide.parentElement,o.panel.querySelector('.observation-content'));assert.equal(o.dock.classList.contains('lesson-guiding'),false);f.finish();assert.equal(f.s.phase,'ready');o.openGuide();assert.match(go.textContent,/领取/);o.open(false);assert.equal(o.guide.open,false);assert.equal(o.primary.parentElement,o.dock);assert.equal(f.s.phase,'ready');f.action('collect');f.finish();assert.equal(f.s.collected,1);
});
test('real guide exposes simulated jam, recovery, continue and cancel without hiding original fault toggle',()=>{
 const f=fixture(),o=f.mount();o.openGuide();assert.equal(o.box.parentElement,o.panel.querySelector('.observation-content'));assert.equal(o.toggle.disabled,false);o.toggle.onchange();o.guide.querySelector('.mechanism-lesson-go').onclick();f.finish();let choices=o.guide.querySelector('.mechanism-lesson-choices');choices.children.find(button=>button.dataset.choice==='flavor-2').onclick();f.finish();assert.equal(f.s.phase,'jammed');assert.match(o.guide.querySelector('.mechanism-lesson-title').textContent,/模拟检测/);assert.equal(o.recover.disabled,false);o.guide.querySelector('.mechanism-lesson-go').onclick();assert.equal(f.s.phase,'recovering');assert.equal(o.guide.querySelector('.mechanism-lesson-go').getAttribute('aria-disabled'),'true');f.finish();assert.equal(f.s.phase,'recovered');assert.equal(o.guide.querySelector('.mechanism-lesson-go').hidden,true);choices=o.guide.querySelector('.mechanism-lesson-choices');assert.deepEqual(choices.children.map(b=>b.dataset.choice),['continue','cancel']);choices.children.find(button=>button.dataset.choice==='cancel').onclick();assert.equal(f.s.phase,'returning');assert.match(o.guide.querySelector('.mechanism-lesson-reason').textContent,/已经归还可售库存/);f.finish();assert.equal(f.s.phase,'idle');assert.equal(f.s.tokens,0);assert.equal(f.s.reservedCoin,0);assert.equal(o.toggle.disabled,false);assert.equal(o.toggle.checked,false);assert.equal(o.guide.querySelector('.mechanism-lesson-go').hidden,false);assert.match(o.guide.querySelector('.mechanism-lesson-go').textContent,/投入/);
});
test('reserve readouts distinguish unused coins, held item and stock restored before refund',()=>{
 const f=fixture();jam(f,1,3);let reads=f.observation().readouts;assert.equal(reads[0].label,'暂存 / 保留币');assert.equal(reads[0].value,'2 / 1 枚');assert.equal(reads[1].label,'可售 / 保留库存');assert.equal(reads[1].value,'8 / 1 罐');f.action('recover');f.finish();reads=f.observation().readouts;assert.equal(reads[1].value,'8 / 1 罐');f.action('refund');assert.equal(f.s.phase,'returning');reads=f.observation().readouts;assert.equal(reads[0].value,'2 / 1 枚');assert.equal(reads[1].value,'9 / 0 罐');f.finish();reads=f.observation().readouts;assert.equal(reads[0].value,'0 / 0 枚');assert.equal(reads[1].value,'9 / 0 罐');
});
test('all scene geometry, shelf painter order and can path source are byte-identical to accepted v12 baseline',()=>{
 const drawing=code=>code.slice(code.indexOf(' function itemPose(s)'),code.indexOf(' const observation='));assert.equal(drawing(source),drawing(baseline));assert(!/setTimeout|setInterval|requestAnimationFrame/.test(source),'lesson adds no scheduler');measurements.push({geometrySourceByteIdentical:true,baseline:'898db54'});
});
test('free play remains exactly baseline-identical at every matched frame, including jam, refund, refill and reset',()=>{
 const f=fixture(),b=fixture(true);let frames=0,renders=0;
 function both(k,i=0){f.action(k,i);b.action(k,i);assert.deepEqual(shared(f),shared(b));let n=0;while(f.pending||b.pending){f.frame();b.frame();assert.deepEqual(shared(f),shared(b),'identical machine state: '+k+' frame '+n);if(n===0||n%17===0||!f.pending){assert.equal(f.render(),b.render(),'identical ordered geometry: '+k+' frame '+n);renders++;}frames++;assert(n++<500);}assert.equal(f.pending,b.pending);}
 for(let i=0;i<3;i++)for(let n=0;n<3;n++){both('token');both('choose',i);both('collect');}both('token');both('token');both('refund');both('refill');for(let i=0;i<3;i++){both('token');both('token');both('faultNext');both('choose',i);both('recover');if(i===1)both('refund');else{both('continue');both('collect');both('refund');}}both('refill');both('reset');measurements.push({exactBaselineFrames:frames,exactOrderedSceneRenders:renders});
});
const report={passed:tests.filter(t=>t.ok).length,total:tests.length,measurements,limits:'Production scene callbacks, complete ordered scene geometry and core RAF; mocked DOM/clock. Actual shared lesson helper mounted with mock DOM, including docking, choices, exit and state refresh. No browser, publication, acoustic listening or real sensor/repair claim.',tests};console.log(JSON.stringify(report,null,2));if(report.passed!==report.total)process.exitCode=1;
